BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS question_source_aliases (
 alias_id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id),
 source TEXT NOT NULL, year INTEGER NOT NULL, set_number INTEGER,
 question_number INTEGER NOT NULL, source_locator TEXT NOT NULL,
 option_map_json TEXT NOT NULL CHECK(json_valid(option_map_json)),
 verification_method TEXT NOT NULL, metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json))
);
CREATE INDEX IF NOT EXISTS question_source_aliases_target ON question_source_aliases(question_id);
CREATE TABLE IF NOT EXISTS session_question_sources (
 session_id TEXT NOT NULL, question_id TEXT NOT NULL, reference_id TEXT NOT NULL,
 source TEXT NOT NULL, source_locator TEXT NOT NULL,
 PRIMARY KEY(session_id,question_id),
 FOREIGN KEY(session_id,question_id) REFERENCES session_questions(session_id,question_id) ON DELETE CASCADE
);
